export function auth0Audience() {
  const audience = process.env.AUTH0_AUDIENCE;
  if (!audience || !URL.canParse(audience)) {
    throw new Error('AUTH0_AUDIENCE must be an absolute URL matching the Auth0 API identifier');
  }
  return audience;
}

