  const domain = process.env.AUTH0_DOMAIN;
  if (!domain || !/^[a-z0-9.-]+$/i.test(domain)) {
    throw new Error('AUTH0_DOMAIN must be a hostname');
  }
  return `https://${domain}/`;
}
